Your expense tracker is below. Add an item, amount and category, set a monthly budget, and the totals update as you go. Entries stay only while this page is open, so I can set up a monthly routine to ask you for the numbers if you want them kept.

```page
<!DOCTYPE html>
<html><head><meta charset="utf-8"><title>Monthly expenses</title>
<style>
body{font-family:Segoe UI,Arial,sans-serif;margin:0;padding:16px;background:#f6f6f8;color:#222}
h2{margin:0 0 12px}
.card{background:#fff;border-radius:10px;padding:12px;margin-bottom:12px;box-shadow:0 1px 3px #0001}
.row{display:flex;gap:8px;flex-wrap:wrap}
input,select,button{padding:8px;border:1px solid #ccc;border-radius:6px;font-size:14px}
button{background:#2b6cb0;color:#fff;border:0;cursor:pointer}
button.x{background:#c53030;padding:4px 8px}
.big{font-size:22px;font-weight:600}
.bar{height:10px;background:#e2e8f0;border-radius:5px;overflow:hidden}
.fill{height:100%;background:#2b6cb0}
.over{background:#c53030}
.item{display:flex;justify-content:space-between;align-items:center;padding:6px 0;border-bottom:1px solid #eee}
.muted{color:#666;font-size:13px}
</style></head><body>
<h2 id="title">Expenses</h2>
<div class="card">
 <div class="row">
  <input id="name" placeholder="What for?" style="flex:2;min-width:120px">
  <input id="amt" type="number" min="0" placeholder="Amount (₹)" style="flex:1;min-width:100px">
  <select id="cat"><option>Food</option><option>Rent</option><option>Travel</option><option>Bills</option><option>Shopping</option><option>Other</option></select>
  <button id="add">Add</button>
 </div>
</div>
<div class="card">
 <div class="row" style="align-items:center;justify-content:space-between">
  <div><div class="muted">Spent this month</div><div class="big" id="total">₹0</div></div>
  <div><div class="muted">Monthly budget (₹)</div><input id="budget" type="number" min="0" value="30000" style="width:120px"></div>
 </div>
 <div class="bar" style="margin:10px 0 6px"><div class="fill" id="bf" style="width:0"></div></div>
 <div class="muted" id="left"></div>
</div>
<div class="card"><b>By category</b><div id="cats" class="muted" style="margin-top:8px"></div></div>
<div class="card"><b>Entries</b><div id="list"></div></div>
<script>
var items=[];
var d=new Date();
document.getElementById('title').textContent='Expenses for '+d.toLocaleString('en-IN',{month:'long',year:'numeric'});
function inr(n){return '₹'+Math.round(n).toLocaleString('en-IN');}
function render(){
 var total=0,by={};
 items.forEach(function(i){total+=i.a;by[i.c]=(by[i.c]||0)+i.a;});
 document.getElementById('total').textContent=inr(total);
 var b=parseFloat(document.getElementById('budget').value)||0;
 var pct=b>0?Math.min(100,total/b*100):0;
 var f=document.getElementById('bf');
 f.style.width=pct+'%';
 f.className='fill'+(b>0&&total>b?' over':'');
 document.getElementById('left').textContent=b>0?(total>b?'Over budget by '+inr(total-b):inr(b-total)+' left'):'Set a budget to see what is left';
 var ch='';
 Object.keys(by).forEach(function(k){
  var p=total?by[k]/total*100:0;
  ch+='<div style="margin-bottom:8px"><div class="item" style="border:0;padding:0"><span>'+k+'</span><span>'+inr(by[k])+'</span></div><div class="bar"><div class="fill" style="width:'+p+'%"></div></div></div>';
 });
 document.getElementById('cats').innerHTML=ch||'Nothing yet';
 var l='';
 items.forEach(function(i,idx){
  l+='<div class="item"><span>'+i.n.replace(/</g,'&lt;')+' <span class="muted">· '+i.c+'</span></span><span>'+inr(i.a)+' <button class="x" data-i="'+idx+'">✕</button></span></div>';
 });
 document.getElementById('list').innerHTML=l||'<div class="muted">No entries yet</div>';
}
document.getElementById('add').onclick=function(){
 var n=document.getElementById('name').value.trim();
 var a=parseFloat(document.getElementById('amt').value);
 if(!n||!(a>0))return;
 items.unshift({n:n,a:a,c:document.getElementById('cat').value});
 document.getElementById('name').value='';
 document.getElementById('amt').value='';
 render();
};
document.getElementById('list').onclick=function(e){
 var i=e.target.getAttribute('data-i');
 if(i!==null){items.splice(parseInt(i,10),1);render();}
};
document.getElementById('budget').oninput=render;
render();
</script></body></html>
```

